<script setup>import{ref}from'vue';import{cart,cartTotal}from'../stores';import api from'../services/api';import{useRouter}from'vue-router';const router=useRouter(),address=ref(''),affiliateCode=ref(''),error=ref('');async function submit(){try{await api.post('/orders',{affiliateCode:affiliateCode.value||undefined,shippingAddress:{address:address.value}});cart.items=[];localStorage.removeItem('cart');router.push('/orders')}catch(e){error.value=e.response?.data?.message||'Unable to place order'}}}</script><template><section class="mx-auto max-w-2xl"><h1 class="text-3xl font-black">Checkout</h1><div class="mt-7 rounded-2xl border bg-white p-6"><label class="font-bold">Shipping address</label><textarea v-model="address" required rows="4" class="mt-2 w-full rounded-xl border p-3"></textarea><label class="mt-5 block font-bold">Affiliate code <span class="font-normal text-slate-400">(optional)</span></label><input v-model="affiliateCode" class="mt-2 w-full rounded-xl border p-3"/><p v-if="error" class="mt-3 text-red-600">{{error}}</p><div class="mt-6 flex justify-between border-t pt-5 font-black"><span>Total</span><span>{{cartTotal.toLocaleString()}} ETB</span></div><button @click="submit" class="mt-5 w-full rounded-xl bg-indigo-600 py-3 font-bold text-white">Place order</button></div></section></template>